import {bindHint} from './hint.js';
import * as E from './engine.js';
import {aiOrder} from './ai.js';
import {TITLE,SPECIES,SPEC,TECHS,TECH,SHIPS,PARTS,PART,RES,INCOME,COLORS,RULES} from './data.js';
import {saveGame,loadGame,saveInfo,parseImport,exportText} from './storage.js';
import {HELP,getHelp,getGuidance} from './help.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={galaxy:'M3 9l9-6 9 6v7l-9 6-9-6z M3 9l9 6 9-6 M12 15v7 M12 3v6',research:'M9 3h6 M10 3v6L4 19a1 1 0 001 2h14a1 1 0 001-2L14 9V3 M7 15h10',shipyard:'M12 2l7 15-7-3-7 3z M8 19l-1 3 M12 18v4 M16 19l1 3',empire:'M3 21h18 M5 21V9l7-6 7 6v12 M8 12v5 M12 12v5 M16 12v5',diplomacy:'M8 8a3 3 0 100-6 3 3 0 000 6z M16 10a3 3 0 100-6 M2 19v-3a5 5 0 0110 0v3 M14 13a5 5 0 018 3v3',log:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',save:'M4 3h13l4 4v14H3V3z M7 3v6h9V3 M7 21v-8h10v8',new:'M12 4v16 M4 12h16',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M5 5l14 14 M19 5L5 19',arrow:'M5 12h14 M13 6l6 6-6 6',explore:'M12 3l3 6 6 3-6 3-3 6-3-6-6-3 6-3z',influence:'M12 3a9 9 0 100 18 9 9 0 000-18z M8 12h8 M12 8v8',upgrade:'M12 21V4 M6 10l6-6 6 6 M5 17h3 M16 17h3',build:'M3 8l9-5 9 5-9 5z M3 8v10l9 4 9-4V8 M12 13v9',move:'M3 12h18 M15 6l6 6-6 6 M3 6h4 M3 18h4',pass:'M6 4v16 M11 4l10 8-10 8z',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',help:'M12 3a9 9 0 100 18 9 9 0 000-18z M9 9a3 3 0 116 0c0 2-3 2-3 4 M12 17h.01',zoom:'M4 10a6 6 0 1012 0 6 6 0 00-12 0 M15 15l6 6 M10 7v6 M7 10h6',minus:'M5 12h14',fit:'M3 9V3h6 M15 3h6v6 M21 15v6h-6 M9 21H3v-6',trade:'M4 8h15 M15 4l4 4-4 4 M20 16H5 M9 12l-4 4 4 4',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',play:'M7 4l14 8-14 8z',pause:'M8 4v16 M16 4v16',clock:'M12 3a9 9 0 100 18 9 9 0 000-18z M12 7v5l4 2',star:'M12 3l3 6 6 1-4 5 1 6-6-3-6 3 1-6-4-5 6-1z',check:'M4 12l5 5L20 6'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.galaxy}"/></svg>`;
const shipSVG=type=>`<svg class="fleet-glyph" viewBox="0 0 100 60" fill="currentColor" aria-hidden="true">${type==='dreadnought'?'<path d="M50 2l13 15h15l12 32-22-8-9 14H41l-9-14-22 8 12-32h15z"/><path d="M46 14h8v31h-8z" fill="#10141f"/>':type==='cruiser'?'<path d="M50 3l13 23 13-8 15 30-30-9-11 17-11-17-30 9 15-30 13 8z"/><path d="M47 15h6v27h-6z" fill="#10141f"/>':type==='starbase'?'<path d="M43 4h14l5 13 17-1 7 12-10 10 1 16-17-3-10 8-10-8-17 3 1-16-10-10 7-12 17 1z"/><circle cx="50" cy="30" r="12" fill="#10141f"/>':type==='ancient'||type==='gcds'?'<path d="M50 4l11 15 20 5-8 18-23 15-23-15-8-18 20-5z"/><circle cx="50" cy="30" r="12" fill="#10141f"/>':'<path d="M50 3l12 29 23 18-30-9-5 15-5-15-30 9 23-18z"/>'}</svg>`;
let state,view='galaxy',selected='2,0',moving=null,paused=false,autoCombat=false,timer=null,speed=450,draft={},zoom=1,pan={x:0,y:0},lastSave='',storageError=false,setupCount=3,setupSpecies='terran',setupLevel='normal',setupMode='solo',exploreChoice=0,exploreRotation=0,chosenDie=0;
let loaded=false;try{const saved=loadGame();if(saved){state=saved.game;lastSave=saved.savedAt;loaded=true;}}catch{try{const backup=loadGame('backup');if(backup){state=backup.game;loaded=true;}}catch{}}
state??=E.newGame({players:[{species:'terran',ai:false},{species:'hydran',ai:true},{species:'orion',ai:true}]});
const me=()=>state.mode==='hotseat'&&state.phase==='action'&&!state.players[state.turn].ai?state.turn:state.players.find(p=>!p.ai)?.id??0;
const actor=()=>state.pending[0]?.owner??(state.phase==='upkeep'?state.upkeepIndex:state.phase==='bombardment'?state.bombardOwner:state.phase==='conquest'?state.conquestOwner:state.turn);
const canPlay=()=>state.phase==='action'&&state.turn===me()&&!state.pending.length;
const active=n=>canPlay()&&state.active?.type===n;
const turnName=()=>E.name(state,actor());
const date=v=>new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function persist(){try{saveGame(state);lastSave=new Date().toISOString();storageError=false;}catch{storageError=true;toast('Device storage is unavailable or full. Export a save file to preserve this game.');}}
function run(a,{silent=false}={}){try{state=E.apply(state,a);persist();if(a.type==='finish'||a.type==='pass')moving=null;render();if(state.exploration&&!state.players[state.turn].ai&&!silent)exploreDialog();if(state.pending.length&&!state.players[state.pending[0].owner].ai&&!silent)pendingDialog();schedule();return true;}catch(e){if(!silent)toast(e.message);return false;}}
function modal(title,body,close=true){clearTimeout(timer);closeHelp(false,false);const d=$('#dialog');d.innerHTML=`<div class="dialoghead"><div class="dialog-title-row"><h2 id="dialog-title">${esc(title)}</h2>${helpButton(modalHelp(title))}</div>${close?`<button class="iconbtn" data-cmd="close" aria-label="Close dialog">${icon('close')}</button>`:''}</div><div class="dialogbody">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){$('#dialog').close();schedule();}
const btn=(cmd,label,opts='')=>{const match=opts.match(/class="([^"]*)"/);return `<button class="${match?match[1]:'btn'}" data-cmd="${cmd}" ${opts.replace(/class="[^"]*"/,'')}>${label}</button>`;};
const PAGE_HELP={galaxy:'overview',research:'technology',shipyard:'blueprint',empire:'upkeep',diplomacy:'diplomacy',log:'chronicle',rules:'overview'};
let helpOpen=false,helpAnchor=null,helpTopic=null;
const helpButton=(topic,label='')=>`<button type="button" class="help-trigger" data-help="${esc(topic)}" aria-label="Help: ${esc(label||HELP[topic]?.title||topic.replace(/^(tech|part|species):/,''))}" aria-controls="game-help" aria-expanded="false" title="Help: ${esc(label||HELP[topic]?.title||'Learn more')}"><span aria-hidden="true">?</span></button>`;
function closeHelp(restoreFocus=false,resume=true){if(!helpOpen)return;const panel=$('#game-help'),anchor=helpAnchor;helpOpen=false;helpAnchor=null;helpTopic=null;if(anchor?.isConnected)anchor.setAttribute('aria-expanded','false');if(panel){if(panel.hidePopover)try{panel.hidePopover();}catch{}panel.hidden=true;panel.classList.remove('help-visible');}if(restoreFocus&&anchor?.isConnected)anchor.focus();if(resume)schedule();}
function openHelp(topic,anchor){if(helpOpen&&helpAnchor===anchor){closeHelp(true);return;}closeHelp(false,false);clearTimeout(timer);const content=getHelp(state,me(),topic);let panel=$('#game-help');if(!panel){panel=document.createElement('section');panel.id='game-help';panel.setAttribute('popover','manual');panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','game-help-title');panel.tabIndex=-1;document.body.append(panel);}panel.innerHTML=`<div class="help-popover-head"><h2 id="game-help-title">${esc(content.title)}</h2><button class="iconbtn" data-help-close="true" aria-label="Close help">${icon('close')}</button></div><p>${esc(content.text)}</p>${content.steps?.length?`<ol>${content.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}${content.context?`<div class="help-context"><strong>Right now</strong><p>${esc(content.context)}</p></div>`:''}<div class="help-dismiss-hint">Tap outside or press Escape to close.</div>`;helpOpen=true;helpAnchor=anchor;helpTopic=topic;anchor.setAttribute('aria-expanded','true');const helpHost=$('#dialog').open?$('#dialog'):document.body;if(panel.parentElement!==helpHost)helpHost.append(panel);panel.hidden=false;panel.classList.add('help-visible');if(panel.showPopover)panel.showPopover();else ($('#dialog').open?$('#dialog'):document.body).append(panel);const w=document.documentElement.clientWidth,h=window.visualViewport?.height||window.innerHeight;panel.style.width=Math.min(370,w-24)+'px';panel.style.maxHeight=(h-24)+'px';const rect=anchor.getBoundingClientRect(),height=panel.getBoundingClientRect().height,width=panel.getBoundingClientRect().width;panel.style.left=Math.max(12,Math.min(rect.right-width,w-width-12))+'px';panel.style.top=Math.max(12,rect.bottom+height+8<h?rect.bottom+8:rect.top-height-8)+'px';panel.focus({preventScroll:true});}
function modalHelp(title){if(title.startsWith('Construct at'))return'build';return {'Uncharted space':'explore','A discovery awaits':'discovery','Ancient technology':'technology','Combat reputation':'reputation','Bank conversion':'trade','Colonize population square':'colonies','Deploy colony ships':'colonies','New game':'setup','Welcome to E:NDftG':'setup','Save & load':'saves','Command center':'overview','AI settings':'ai','Exchange ambassadors':'diplomacy','Declare retreat':'retreat'}[title]||'overview';}
function nextStep(){const g=getGuidance(state,{player:me(),view,moving,paused,autoCombat});return `<section class="next-step" aria-label="What to do next"><div class="next-step-copy"><div class="eyebrow">What to do next</div><h2>${esc(g.title)}</h2><p>${esc(g.text)}</p></div><div class="next-step-controls">${helpButton(g.help,'What to do next')}${g.cta?`<button class="btn small" ${g.cta.view?`data-view="${g.cta.view}"`:`data-cmd="${g.cta.cmd}"`}>${esc(g.cta.label)}</button>`:''}</div></section>`;}
document.addEventListener('pointerdown',e=>{if(helpOpen&&!$('#game-help')?.contains(e.target)&&!e.target.closest('[data-help]'))closeHelp(false);},true);
document.addEventListener('keydown',e=>{if(helpOpen&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeHelp(true);}},true);
window.addEventListener('resize',()=>closeHelp(false));
const pstyle=p=>`style="--player:${p.color}"`;
const navs=[['galaxy','Galaxy','galaxy'],['research','Research','research'],['shipyard','Shipyard','shipyard'],['empire','Civilization','empire'],['diplomacy','Council','diplomacy'],['log','Chronicle','log']];
function nav(mobile=false){return navs.filter((x,i)=>!mobile||i<5).map(([id,label,i])=>`<button class="navitem ${view===id?'selected':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('');}
function render(){closeHelp(false,false);const p=state.players[me()],other=state.players[actor()],isTurn=state.phase==='action'&&state.turn===me();$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>${TITLE}<small>NEW DAWN FOR THE GALAXY</small></div></div><div class="eyebrow">Situation room</div>${nav()}<div class="sidebar-bottom"><div class="eyebrow">Command center</div><button class="navitem" data-cmd="saves">${icon('save')}<span>Save & load</span></button><button class="navitem" data-view="rules">${icon('help')}<span>Rules & coverage</span></button><button class="navitem" data-cmd="new">${icon('new')}<span>New game</span></button><div class="sidebar-foot"><span class="dot"></span>Local command · ${state.mode==='solo'?'solo':'hotseat'}<br>First edition · nine rounds<br>Implementation alpha 0.1</div></div></aside><div class="workspace"><header class="topbar"><div class="brand mobile-brand"><img src="icon.svg" alt=""><span>${TITLE}</span></div><div class="top-status"><span class="eyebrow">Galactic command</span><span class="tag">ROUND ${state.round} / 9</span><span class="pill"><span class="dot"></span>${esc(phaseName())}</span></div><div class="top-actions"><button type="button" class="btn" data-hint-show aria-label="Hint: explain the AI’s next move">Hint</button><button class="iconbtn" data-cmd="toggle-pause" aria-label="${paused?'Resume':'Pause'} AI" title="${paused?'Resume':'Pause'} AI">${icon(paused?'play':'pause')}</button><button class="iconbtn" data-cmd="saves" aria-label="Save and load" title="Save and load">${icon('save')}</button><button class="iconbtn" data-cmd="menu" aria-label="Menu">${icon('menu')}</button></div></header><main class="content" id="content"><div class="pagehead"><div><div class="eyebrow">${esc(SPEC[p.species].tag)}</div><div class="heading-help"><h1>${{galaxy:'The galactic frontier',research:'Research & technology',shipyard:'Fleet blueprints',empire:'Your civilization',diplomacy:'The Galactic Council',log:'Galactic chronicle',rules:'Rules & implementation'}[view]||'Command center'}</h1>${helpButton(PAGE_HELP[view]||'overview')}</div><p>${{galaxy:'Explore the unknown. Shape the next dawn.',research:'Science changes the balance of power.',shipyard:'Every part changes every ship of its class.',empire:'Influence, production and the paths to victory.',diplomacy:'Make connections. Choose your loyalties.',log:'A record of every move, discovery and conflict.',rules:'First edition base game · 2011 · nine rounds.'}[view]}</p></div><div class="turnbadge">${paused?'AI paused':isTurn?'Your turn':other?.ai?'AI turn':esc(turnName())}<span class="desktop-label"> · ${state.phase==='action'?'Action phase':esc(phaseName())}</span></div></div>${nextStep()}<div class="res-grid">${RES.map((r,i)=>`<div class="resource"><div class="resname">${['Money','Science','Materials'][i]}${helpButton(r)}</div><div class="value ${r}">${p.resources[r]}</div><div class="income">+${E.income(state,p.id,r)} / round${r==='money'?` · −${E.upkeep(state,p.id)} upkeep`:''}</div><div class="res-symbol ${r}">${['◈','⬡','▰'][i]}</div></div>`).join('')}</div><div class="players">${state.players.map(x=>`<div class="playerchip ${actor()===x.id?'current':''}" ${pstyle(x)}><div class="avatar">${['✧','◉','⌬','❋','◇','⌘','⟐'][SPECIES.findIndex(y=>y.id===x.species)]}</div><div><div class="name">${esc(x.name)}</div><div class="sub">${x.ai?`${x.difficulty} AI`:'Local commander'}${x.passed?' · Passed':''}</div></div><div class="points">${E.totalScore(state,x.id)} <small>VP</small></div></div>`).join('')}</div>${state.phase!=='action'?phasePanel():''}${state.pending.length?`<div class="phase-banner between"><span>${esc(E.name(state,state.pending[0].owner))}: ${esc(state.pending[0].kind==='reputation'?'reputation draw':'discovery choice')}</span>${btn('pending','Resolve choice','class="btn primary"')}</div>`:''}${view==='galaxy'?galaxy():view==='research'?researchView():view==='shipyard'?shipyardView():view==='empire'?empireView():view==='diplomacy'?councilView():view==='log'?logView():rulesView()}<div class="footertext">E:NDftG · Unofficial adaptation of Eclipse: New Dawn for the Galaxy. Original interface and vector component artwork.<br>${storageError?'Save unavailable — export a file.':lastSave?'Autosaved on this device · '+date(lastSave):'Saves stay on this device. Export a file to move between devices.'} <button class="textlink" data-view="rules" style="background:none;border:0;color:var(--muted);font-size:10px;text-decoration:underline;cursor:pointer">Fidelity & known gaps</button></div></main></div><nav class="mobile-nav" aria-label="Game navigation">${nav(true)}</nav>`;
 if(view==='galaxy')bindMap();
}
function phaseName(){return{action:'Action',combat:'Combat',bombardment:'Population attack',conquest:'Conquest',upkeep:'Upkeep',ended:'Game complete'}[state.phase];}
function galaxy(){return`<div class="board-layout"><div><section class="panel board-panel"><div class="panelhead board-head"><div class="boardtitle">${icon('galaxy')}<h2>Galaxy map</h2>${helpButton('map')}</div><span class="eyebrow">${Object.keys(state.sectors).length} charted sectors</span></div><div class="map-wrap">${mapSVG()}<div class="legend"><span><i class="filled"></i>Controlled</span><span><i></i>Unclaimed</span><span>✦ Ancient presence</span></div><div class="map-controls"><button class="iconbtn" data-cmd="zoom-out" aria-label="Zoom out">${icon('minus')}</button><button class="iconbtn" data-cmd="fit" aria-label="Fit map">${icon('fit')}</button><button class="iconbtn" data-cmd="zoom-in" aria-label="Zoom in">${icon('new')}</button></div></div><div class="map-caption">${icon(state.active?.type||'explore')}<span>${mapHint()}</span></div>${actionPanel()}</section><section class="panel activity"><div class="panelhead"><h2>Latest transmissions</h2><button class="iconbtn" data-view="log" aria-label="Open chronicle">${icon('arrow')}</button></div><div class="panelbody" style="padding-top:3px;padding-bottom:3px">${state.log.slice(-3).reverse().map(x=>`<div class="event"><span class="time">R${x.round}</span><p>${esc(x.text)}</p></div>`).join('')}</div></section></div><aside>${sectorPanel()}</aside></div>`;}
function mapHint(){if(state.exploration)return'An explored sector awaits placement. Open the reveal to rotate or discard it.';if(canPlay()&&state.active?.left===0)return'Operations complete. You may colonize or trade, then finish this action.';if(active('explore'))return'Select a dashed frontier hex to reveal a sector.';if(active('influence'))return'Select a vacant sector to claim, or your sector to withdraw.';if(active('move'))return moving?'Select a highlighted destination.':'Select one of your ships, then choose its destination.';if(active('build'))return'Select a controlled sector and choose what to construct.';if(state.players[state.turn]?.ai&&state.phase==='action')return paused?'AI paused. Resume when you are ready.':`${esc(turnName())} is considering the next order.`;return'Drag to pan · pinch or use + / − to zoom · select a sector to inspect.';}
function actionPanel(){const p=state.players[me()],ac=state.active,mine=canPlay();return`<div class="actionpanel"><div class="between"><div class="eyebrow">${ac?`${esc(ac.type)} ${ac.reaction?'reaction':''} · ${ac.left} remaining`:p.passed?'Reaction orders':'Issue an order'}</div><div class="help-label"><span class="muted" style="font-size:10px">${E.discs(state,p.id)} influence available</span>${helpButton('upkeep')}</div></div><div class="actions">${['explore','influence','research','upgrade','build','move'].map(n=>`<div class="action-option"><button class="action ${ac?.type===n?'active':''}" data-action="${n}" ${!mine||ac||E.discs(state,p.id)<1||p.passed&&!['build','upgrade','move'].includes(n)?'disabled':''}>${icon(n==='research'?'research':n)}<span>${n[0].toUpperCase()+n.slice(1)}</span></button>${helpButton(n)}</div>`).join('')}</div><div class="action-footer"><div><div class="influence" aria-label="${E.discs(state,p.id)} available influence discs">${Array.from({length:p.discs},(_,i)=>`<i class="${i<E.discs(state,p.id)?'free':i<p.discs-E.controlled(state,p.id).length?'used':''}"></i>`).join('')}</div><span class="muted" style="font-size:10px">Projected upkeep <b style="color:var(--gold)">${E.upkeep(state,p.id)}</b> · Money income ${E.income(state,p.id,'money')}</span></div><div class="flex">${ac&&mine?btn('finish','Finish action',`class="btn primary" ${state.exploration?'disabled':''}`):btn('pass',p.passed?'Skip reaction':'Pass',`${!mine?'disabled':''}`)}${helpButton(ac&&mine?'finish':'pass')}</div></div>${active('influence')?`<div class="spacer"></div>${btn('refresh',`Refresh up to 2 colony ships (${p.colony}/${SPEC[p.species].colony} ready)`,`${ac.refreshed?'disabled':''}`)}`:''}${state.exploration?`<div class="spacer"></div>${btn('reveal','Open explored sector','class="btn teal full"')}`:''}</div>`;}
const hexPoints=(radius=68)=>Array.from({length:6},(_,i)=>{const a=(i*60-30)*Math.PI/180;return`${Math.cos(a)*radius},${Math.sin(a)*radius}`;}).join(' ');
const xy=t=>({x:Math.sqrt(3)*72*(t.q+t.r/2),y:108*t.r});
function miniSector(t,rotation=t.rotation){const cc=t.owner!==null?state.players[t.owner]?.color:'#8898b6';return`<polygon class="hex" points="${hexPoints()}"/><path d="M-43 -37L43 -37M-43 37L43 37" stroke="#ffffff06"/>${t.ports.map(d=>{const a=(d+rotation)*Math.PI/3;return`<line x1="${Math.cos(a)*55}" y1="${Math.sin(a)*55}" x2="${Math.cos(a)*67}" y2="${Math.sin(a)*67}" stroke="#b3c5ed" stroke-width="3" opacity=".7"/>`;}).join('')}<circle cy="-9" r="22" fill="url(#planet${t.id%5})"/><ellipse cy="-9" rx="34" ry="9" fill="none" stroke="#aaaaff1a" transform="rotate(-25)"/><text y="-45" text-anchor="middle" class="sector-id">${String(t.id).padStart(3,'0')}</text><text y="26" text-anchor="middle" class="sector-title">${esc(t.name)}</text><text x="-40" y="2" class="sector-value">${t.vp}✧</text>${t.owner!==null?`<circle cx="39" cy="-1" r="5" fill="${cc}"/>`:''}${t.artifact?'<text x="-38" y="-17" fill="#d5ae7f" font-size="10">◈</text>':''}${t.discovery?'<text x="38" y="-18" fill="#b9a0e7" font-size="9">?</text>':''}<g transform="translate(${-t.slots.length*5},36)">${t.slots.map((p,i)=>`<rect x="${i*10}" y="0" width="6" height="6" rx="1" fill="${p.cube?(state.players[p.cube.owner]?.color||'white'):({money:'#b39052',science:'#9272b5',materials:'#967357',wild:'#818ca2',orbital:'#818ca2'})[p.type]}" stroke="${p.advanced?'#f1d58c':'#ffffff20'}" stroke-width="${p.advanced?1:0.5}" opacity="${p.cube?1:.5}"/>`).join('')}</g>${t.ships.length?`<g transform="translate(0,49)">${[...new Set(t.ships.map(u=>u.owner))].map((o,i)=>`<text x="${i*21-([...new Set(t.ships.map(u=>u.owner))].length-1)*10}" text-anchor="middle" fill="${typeof o==='number'?state.players[o].color:'#ee9d82'}" font-size="9">${typeof o==='string'?'✦':'➤'}${t.ships.filter(u=>u.owner===o).length}</text>`).join('')}</g>`:''}`;}
function defs(){return`<defs><radialGradient id="hexFill" cx="40%" cy="35%"><stop offset="0" stop-color="#25314a"/><stop offset="1" stop-color="#141c2c"/></radialGradient>${['#7798af','#b99f76','#8f7da8','#7c9f8f','#a57983'].map((c,i)=>`<radialGradient id="planet${i}" cx="30%" cy="30%"><stop offset="0" stop-color="${c}"/><stop offset=".55" stop-color="${c}" stop-opacity=".55"/><stop offset="1" stop-color="#101827"/></radialGradient>`).join('')}</defs>`;}
function mapSVG(){const sectors=Object.values(state.sectors),fs=active('explore')&&state.active.left>0?E.frontiers(state,me()):[],reach=moving?E.reachable(state,Object.values(state.sectors).flatMap(t=>t.ships).find(u=>u.id===moving)||{}):[],all=[...sectors,...fs],coords=all.map(xy);let minX=Math.min(...coords.map(x=>x.x))-110,maxX=Math.max(...coords.map(x=>x.x))+110,minY=Math.min(...coords.map(x=>x.y))-100,maxY=Math.max(...coords.map(x=>x.y))+100;const width=Math.max(500,maxX-minX),height=Math.max(430,maxY-minY),cx=(minX+maxX)/2,cy=(minY+maxY)/2;const vb=`${cx-width/zoom/2-pan.x} ${cy-height/zoom/2-pan.y} ${width/zoom} ${height/zoom}`;return`<svg id="galaxy-map" viewBox="${vb}" role="group" aria-label="Interactive galaxy map"><title>Galaxy map: select a sector or an unexplored frontier</title>${defs()}<g opacity=".45">${Array.from({length:100},(_,i)=>`<circle cx="${minX+((i*137.08)%width)}" cy="${minY+((i*79.61)%height)}" r="${i%9===0?1.2:.6}" fill="#9baed1"/>`).join('')}</g><g>${sectors.map(t=>{const c=xy(t),target=reach.some(x=>x.key===t.key);return`<g class="sector ${selected===t.key?'selected':''} ${target?'target':''}" transform="translate(${c.x} ${c.y})" data-sector="${t.key}" role="button" tabindex="0" aria-label="${esc(t.name)} sector ${t.id}, ${t.owner===null?'unclaimed':esc(state.players[t.owner].name)}, ${t.ships.length} ships">${miniSector(t)}</g>`;}).join('')}${fs.map(t=>{const c=xy(t);return`<g class="sector frontier" transform="translate(${c.x} ${c.y})" data-frontier="${t.key}" role="button" tabindex="0" aria-label="Explore ring ${t.ring} at ${t.key}"><polygon class="hex" points="${hexPoints()}"/><text text-anchor="middle" y="3" font-size="25" fill="#68d6c380">+</text><text text-anchor="middle" y="24" font-size="8" fill="#68d6c380" letter-spacing="1.5">SECTOR ${t.ring}</text></g>`;}).join('')}</g></svg>`;}
function bindMap(){const svg=$('#galaxy-map');if(!svg)return;const pts=new Map();let drag=null,pinch=null,moved=false;svg.addEventListener('pointerdown',e=>{pts.set(e.pointerId,{x:e.clientX,y:e.clientY});svg.setPointerCapture(e.pointerId);moved=false;if(pts.size===1)drag={x:e.clientX,y:e.clientY,pan:{...pan},target:e.target.closest('[data-sector],[data-frontier]')};if(pts.size===2){const p=[...pts.values()];pinch={d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),zoom};}});svg.addEventListener('pointermove',e=>{if(!pts.has(e.pointerId))return;pts.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pts.size===2&&pinch){const p=[...pts.values()];zoom=Math.max(.6,Math.min(4,pinch.zoom*Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)/pinch.d));moved=true;}else if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5){moved=true;const box=svg.viewBox.baseVal,rect=svg.getBoundingClientRect();pan={x:drag.pan.x+dx*box.width/rect.width,y:drag.pan.y+dy*box.height/rect.height};}}if(moved){const replacement=new DOMParser().parseFromString(mapSVG(),'image/svg+xml').documentElement;svg.setAttribute('viewBox',replacement.getAttribute('viewBox'));}});svg.addEventListener('pointerup',e=>{pts.delete(e.pointerId);if(!moved){const el=drag?.target;if(el?.dataset.frontier)doFrontier(el.dataset.frontier);else if(el?.dataset.sector)selectSector(el.dataset.sector);}if(!pts.size){drag=null;pinch=null;}});svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const el=e.target.closest('[data-sector],[data-frontier]');if(el?.dataset.frontier)doFrontier(el.dataset.frontier);else if(el?.dataset.sector)selectSector(el.dataset.sector);}});svg.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();zoom=Math.max(.6,Math.min(4,zoom*(e.deltaY<0?1.12:.9)));render();},{passive:false});}
function selectSector(k){if(active('move')&&moving){if(run({type:'move',ship:moving,target:k})){moving=null;selected=k;}else selected=k;}else selected=k;render();}
function doFrontier(k){if(run({type:'explore',target:k})){exploreRotation=0;exploreChoice=0;exploreDialog();}}
function sectorPanel(){const t=state.sectors[selected],p=state.players[me()];if(!t)return`<section class="panel empty">${icon('galaxy')}<h2>Select a sector</h2><p>Inspect population, ships, wormholes and the commands available here.</p></section>`;const owner=t.owner!==null?state.players[t.owner]:null,cols=E.availableColonies(state,p.id).filter(x=>x.sector===t.key),myTurn=canPlay();return`<section class="panel"><div class="sector-art" style="--planet:${owner?.color||'#8c82aa'}"><span class="art-label">${t.ring===0?'GALACTIC CENTER':t.ring===1?'INNER SECTOR':t.ring===2?'MIDDLE SECTOR':'OUTER SECTOR'} · ${String(t.id).padStart(3,'0')}</span></div><div class="sector-info"><div class="between"><div><h2>${esc(t.name)}</h2><p style="font-size:10px">${owner?esc(owner.name):'Unclaimed space'}</p></div><span class="tag money">${t.vp} VP</span></div><div class="statrow"><div class="statbox"><strong>${t.ships.length}</strong><span>SHIPS</span></div><div class="statbox"><strong>${t.slots.filter(x=>x.cube).length}/${t.slots.length}</strong><span>POPULATION</span></div><div class="statbox"><strong>${t.ports.length}</strong><span>WORMHOLES</span>${helpButton('wormholes')}</div></div><div class="section-label help-label">Population squares${helpButton('population')}</div><div class="pop-row">${t.slots.map((x,i)=>`<button class="pop ${x.cube?'occupied':''}" style="--popcolor:${x.cube?state.players[x.cube.owner].color:'#929eb3'}" data-colony="${i}" data-colony-sector="${t.key}" title="${esc(x.type)}${x.advanced?' · advanced':''}${x.cube?' · occupied':''}" aria-label="${esc(x.type)} population square ${i+1}${x.advanced?' advanced':''}${x.cube?' occupied':''}" ${!cols.some(c=>c.index===i)||!(myTurn||state.phase==='upkeep'&&state.upkeepIndex===p.id)?'disabled':''}>${x.cube?'■':{money:'◈',science:'⬡',materials:'▰',wild:'◇',orbital:'◎'}[x.type]}${x.advanced?'<span class="advanced">★</span>':''}</button>`).join('')}</div><p style="font-size:9px;margin-top:8px">${owner?.id===p.id?`${p.colony} colony ships ready. Tap an empty square to colonize.`:'Control this sector to colonize its worlds.'}</p>${t.artifact?'<div class="section-label money">◈ Ancient artifact</div>':''}${t.discovery?'<div class="section-label science">? Unclaimed discovery</div>':''}${t.structures.length?`<div class="section-label">Structures</div><p style="font-size:11px">${t.structures.map(x=>esc(SHIPS[x].name)).join(' · ')}</p>`:''}<div class="section-label help-label">Ships in sector${helpButton('ships')}</div>${t.ships.length?t.ships.map(u=>unitRow(u)).join(''):'<p style="font-size:11px">No ships stationed here.</p>'}<div class="spacer"></div><div class="stack">${active('influence')&&E.canClaim(state,t,p.id)?btn('claim','Place influence',`data-key="${t.key}" class="btn teal full"`):''}${(active('influence')||state.phase==='upkeep'&&state.upkeepIndex===p.id)&&t.owner===p.id?btn('withdraw','Withdraw influence',`data-key="${t.key}" class="btn danger full"`):''}${t.owner===p.id?btn('construction','Construction',`data-key="${t.key}" class="btn full" ${!myTurn?'disabled':''}`):''}${moving?btn('cancel-move','Cancel ship selection'):''}</div></div></section>`;}
function unitRow(u,combat=false){const owner=typeof u.owner==='number'?state.players[u.owner]:null,st=E.stats(state,u.owner,u.type);return`<div class="unitrow ${moving===u.id?'selected':''}" style="--player:${owner?.color||'#e9a07c'}"><div class="uniticon">${shipSVG(u.type)}</div><div><div class="unitname">${esc(SHIPS[u.type]?.name||u.type.toUpperCase())}</div><div class="unitdetail">${st.hull+1-u.damage}/${st.hull+1} hull · ${st.initiative} init${st.move?' · '+st.move+' move':''}</div></div>${!combat&&u.owner===me()&&u.type!=='starbase'?`<button class="btn small" data-ship="${u.id}" ${!active('move')?'disabled':''}>Select</button>`:''}</div>`;}
function researchView(){const p=state.players[me()];return`${!active('research')?`<div class="notice">Research requires an influence disc. ${btn('start-research','Begin research',`${!canPlay()||state.active||p.passed?'disabled':''}`)}</div>`:`<div class="notice between"><span>${state.active.left} research purchase${state.active.left===1?'':'s'} remaining. Technology discounts apply immediately.</span>${btn('finish','Finish action','class="btn primary"')}</div>`}<div class="tech-grid">${['military','grid','nano'].map((track,i)=>{const count=p.tech.filter(x=>TECH[x].track===track).length;return`<section class="panel techcol"><h2><span style="color:${[COLORS[1],COLORS[0],COLORS[2]][i]}">${icon(i===0?'shipyard':i===1?'galaxy':'research')}</span>${['Military','Grid','Nano'][i]}${helpButton('technology')}</h2><p style="font-size:10px">${count}/7 researched · ${count>3?[0,0,0,0,1,2,3,5][count]:0} VP</p><div class="techtrack">${[0,1,2,3,4,6,8].map((v,i)=>`<span class="${i<count?'owned':''}">−${v}</span>`).join('')}</div>${TECHS.filter(t=>t.track===track).map(t=>{const owned=p.tech.includes(t.id),qty=state.supply[t.id]||0,c=E.techCost(p,t);return`<div class="techrow ${owned?'owned':''}"><div class="between"><h3 class="help-label">${esc(t.name)}${helpButton('tech:'+t.id,t.name)}</h3>${owned?'<span class="pill">Researched</span>':`<span class="cost">${c}<small> ⬡</small></span>`}</div><p>${esc(t.effect)}</p><div class="between"><span class="qty">${owned?'On your technology track':`${qty} in supply · base ${t.cost} / min ${t.min}`}</span>${!owned?`<button class="btn small" data-tech="${t.id}" ${!active('research')||state.active.left<1||!qty||p.resources.science<c||count>=7?'disabled':''}>Research</button>`:''}</div></div>`;}).join('')}</section>`;}).join('')}</div>`;}
function shipyardView(){const p=state.players[me()];return`${active('upgrade')?`<div class="notice between"><span>${state.active.left} new parts available this action. Remove overlays freely; submit a valid design to apply it.</span>${btn('finish','Finish action','class="btn primary"')}</div>`:`<div class="notice between"><span>All ships of a class share one blueprint. Parts have no resource cost.</span>${btn('start-upgrade','Begin upgrade',`${!canPlay()||state.active?'disabled':''}`)}</div>`}<div class="design-grid">${Object.keys(p.designs).map(type=>{const d=p.designs[type],arr=draft[type]||d.overlay;const copy=structuredClone(state);copy.players[p.id].designs[type].overlay=arr;const st=E.stats(copy,p.id,type);return`<section class="panel blueprint" style="--player:${p.color}"><div class="between"><h2 class="help-label">${SHIPS[type].name}${helpButton('blueprint')}</h2><span class="tag">${E.buildCost(p,type)} Materials</span></div><div class="shiphero">${shipSVG(type)}</div><div class="blueprintstats"><span><b class="${st.energy<0?'warning':''}">${st.energy>=0?'+':''}${st.energy}</b>ENERGY${helpButton('energy')}</span><span><b>${st.initiative}</b>INITIATIVE${helpButton('initiative')}</span><span><b>${st.hull+1}</b>HULL${helpButton('hull')}</span><span><b>${st.move}</b>MOVE${helpButton('drive')}</span><span><b>+${st.computer}</b>COMPUTER${helpButton('computer')}</span><span><b>−${st.shield}</b>SHIELD${helpButton('shield')}</span></div><div class="parts">${d.base.map((base,i)=>{const val=arr[i]??base,part=PART[val];return`<div class="part ${arr[i]!==d.overlay[i]?'changed':''}"><div class="label">SLOT ${i+1}${arr[i]===null?' · Printed':''}</div>${active('upgrade')?`<select data-design="${type}" data-slot="${i}" aria-label="${SHIPS[type].name} slot ${i+1}"><option value="" ${arr[i]===null?'selected':''}>${base?PART[base].name+' (printed)':'Empty (printed)'}</option>${PARTS.filter(x=>!x.tech||p.tech.includes(x.tech)).filter(x=>!x.ancient||p.ancientParts.includes(x.id)||d.overlay[i]===x.id).map(x=>`<option value="${x.id}" ${arr[i]===x.id?'selected':''}>${esc(x.name)}${x.energy?' · '+(x.energy>0?'+':'')+x.energy+'E':''}</option>`).join('')}</select>`:`<div class="partname">${part?esc(part.name):'Empty slot'}</div>${part?helpButton('part:'+part.id,part.name):''}`}<div class="partstats">${part?partSummary(part):'Available for a ship part'}</div></div>`;}).join('')}</div>${d.extra.length||d.energy?`<p style="font-size:10px;margin-top:12px">Fixed: ${[d.energy?'+'+d.energy+' Energy':null,...d.extra.map(x=>PART[x].name)].filter(Boolean).join(' · ')}</p>`:''}<div class="blueprint-footer">${active('upgrade')?`<button class="btn primary small" data-refit="${type}" ${!draft[type]?'disabled':''}>Apply blueprint</button>`:'<span class="muted" style="font-size:10px">'+st.cannons.map(x=>x+' damage').join(' · ')+' cannon'+(st.missiles.length?' · '+st.missiles.length+' missiles':'')+'</span>'}</div></section>`;}).join('')}</div>${p.ancientParts.length?`<div class="spacer"></div><section class="panel panelbody"><h2>Ancient parts in reserve</h2><p>${p.ancientParts.map(x=>esc(PART[x].name)).join(' · ')}</p></section>`:''}`;}
function partSummary(p){return[p.energy?(p.energy>0?'+':'')+p.energy+' energy':'0 energy',p.cannons?.map(x=>x+' cannon').join(' / '),p.missiles?.length?p.missiles.length+' missiles':null,p.hull?'+'+p.hull+' hull':null,p.shield?'−'+p.shield+' shield':null,p.computer?'+'+p.computer+' computer':null,p.move?p.move+' move':null,p.initiative?'+'+p.initiative+' init':null].filter(Boolean).map(esc).join(' · ');}
function empireView(){const p=state.players[me()],sc=E.score(state,p.id);return`<div class="empire-grid"><section class="panel empire-card"><div class="eyebrow">${esc(p.name)}</div><h2 class="help-label">Population & production${helpButton('population')}</h2><p style="font-size:11px">Colonized worlds and ambassador cubes expose higher production.</p>${RES.map(r=>`<div class="section-label ${r}">${r} · +${E.income(state,p.id,r)} per round</div><div class="bartrack" style="--player:${r==='money'?'#e2bd7d':r==='science'?'#bb9ce7':'#b18c70'}">${INCOME.slice(0,12).map((v,i)=>`<span class="${i>=E.deployed(state,p.id,r)?'covered':''}" title="${v} production">${v}</span>`).join('')}</div>`).join('')}<div class="section-label help-label">Colony ships${helpButton('colonies')}</div><div class="flex">${Array.from({length:SPEC[p.species].colony},(_,i)=>`<span class="tag ${i<p.colony?'money':''}">◎ ${i<p.colony?'Ready':'Used'}</span>`).join('')}</div></section><section class="panel empire-card"><div class="eyebrow">Influence economy</div><h2 class="help-label">${E.discs(state,p.id)} discs available${helpButton('upkeep')}</h2><p style="font-size:11px">${E.controlled(state,p.id).length} sectors controlled · ${p.actions.length} actions or reactions.</p><div class="influence">${Array.from({length:p.discs},(_,i)=>`<i class="${i<E.discs(state,p.id)?'free':'used'}"></i>`).join('')}</div><div class="statrow"><div class="statbox"><strong class="money">${E.upkeep(state,p.id)}</strong><span>UPKEEP</span></div><div class="statbox"><strong>${p.resources.money+E.income(state,p.id,'money')-E.upkeep(state,p.id)}</strong><span>PROJECTED MONEY</span></div></div><div class="section-label help-label">Bank conversion · ${SPEC[p.species].trade}:1${helpButton('trade')}</div><p style="font-size:11px;margin-bottom:12px">Trade resources at any time. Resources cannot be exchanged between players.</p>${btn('trade',icon('trade')+' Trade resources','class="btn full"')}<div class="section-label help-label">Species abilities${helpButton('species:'+p.species,SPEC[p.species].name)}</div><p style="font-size:12px">${esc(SPEC[p.species].summary)}</p><div class="section-label">Graveyard</div><p style="font-size:11px">${p.graveyard.length} population cubes return at Cleanup.</p></section><section class="panel empire-card"><div class="eyebrow">Paths to victory</div><h2 class="help-label">Victory points${helpButton('score')}</h2><table class="scoretable"><tbody>${Object.entries(sc).map(([k,v])=>`<tr><td>${k[0].toUpperCase()+k.slice(1)}</td><td>${v}</td></tr>`).join('')}<tr><td><strong>Total</strong></td><td>${E.totalScore(state,p.id)}</td></tr></tbody></table><p style="font-size:10px;margin-top:12px">Reputation totals are visible in this local implementation. Final scores are settled after round nine.</p></section></div>`;}
function councilView(){return`<div class="notice">Diplomatic exchanges are available in four to six player games. Ambassadors require neighboring controlled sectors connected by wormholes.</div><div class="empire-grid">${state.players.filter(x=>x.id!==me()).map(p=>{const allied=state.players[me()].ambassadors.includes(p.id);return`<section class="panel empire-card" ${pstyle(p)}><div class="between"><div class="avatar">${icon('diplomacy')}</div><span class="tag">${p.ai?p.difficulty+' AI':'Local commander'}</span></div><h2 class="help-label">${esc(p.name)}${helpButton('species:'+p.species,SPEC[p.species].name)}</h2><p style="font-size:12px">${esc(SPEC[p.species].summary)}</p><div class="statrow"><div class="statbox"><strong>${E.controlled(state,p.id).length}</strong><span>SECTORS</span></div><div class="statbox"><strong>${E.totalScore(state,p.id)}</strong><span>VP</span></div></div><div class="spacer"></div><button class="btn ${allied?'teal':''} full" data-diplomacy="${p.id}" ${state.players.length<4||!canPlay()||allied?'disabled':''}>${allied?'Diplomatic relations':'Exchange ambassadors'}</button></section>`;}).join('')}</div>${state.traitor!==null?`<div class="spacer"></div><div class="notice">Traitor card: ${esc(state.players[state.traitor].name)} · −2 VP · cannot form new diplomatic relations.</div>`:''}`;}
function logView(){return`<section class="panel"><div class="panelhead"><h2>Mission record</h2><span class="tag">${state.log.length} entries</span></div><div class="panelbody">${[...state.log].reverse().map(x=>`<div class="event"><span class="time">R${x.round}</span><span class="tag">${esc(x.phase)}</span><p>${esc(x.text)}</p></div>`).join('')}</div></section>`;}
function rulesView(){return`<div class="notice"><strong>Implementation alpha — complete component parity is not verified.</strong> The playable game has reconstructed sector layouts, some unverified faction and ancient-part values, and original vector artwork. It is not an exact copy of every printed component.</div><div class="between" style="margin:18px 0"><h2>How to play</h2><a class="btn small" href="https://board-game-rules.com/wp-content/uploads/2025/01/eclipse-new-dawn-for-the-galaxy_Official-Rules.pdf" target="_blank" rel="noopener">First-edition rulebook ${icon('arrow')}</a></div><div class="rules-grid">${RULES.map(([t,b])=>`<details><summary>${esc(t)}</summary><p>${esc(b)}</p></details>`).join('')}</div><div class="verification"><h3>Fidelity and unfinished work</h3><p>The engine implements the core round, action, economy, research, fleet and battle systems. Exact component verification is still required for sector wormholes/population/artifacts, faction blueprint differences, full economic tracks, ancient parts, technology minimum costs and Mechanema construction prices.</p><ul><li>Sector IDs and deck sizes match the base game; individual layouts are reconstructed.</li><li>Faction abilities and starting resources follow the first-edition rulebook. Some blueprint bonuses remain provisional.</li><li>Original vector planets, fleet silhouettes and symbols replace printed artwork.</li><li>Some physical-table choices are automated: population return colors and some discovery benefits require further parity work.</li><li>Local solo and hotseat play are available. Online multiplayer is not implemented.</li></ul><a href="docs/COVERAGE.md" target="_blank">Read the complete coverage and limitations record →</a></div><div class="spacer"></div><section class="panel panelbody"><h2>AI difficulty</h2><p style="font-size:12px;margin-top:9px"><strong>Easy:</strong> randomized priorities and a conservative four-action budget. <strong>Normal:</strong> evaluates production, exploration, research and fleet strength. <strong>Hard:</strong> uses deterministic strategic scoring, assesses battles and retreats from poor engagements. All use the same resources, legal actions and dice as human commanders. These are heuristic opponents, not a competitive-strength guarantee.</p></section>`;}
function phasePanel(){if(state.phase==='combat'){const b=state.battle;if(!b)return'';const t=state.sectors[b.sector],g=E.combatGroup(state),die=b.dice[chosenDie]||b.dice[0],owner=die?.owner??g?.owner,bot=typeof owner==='string'||state.players[owner]?.ai,targets=die?E.hitTargets(state,die):[];return`<section class="combat-banner"><div class="between"><div class="help-label"><span class="eyebrow" style="color:var(--coral)">Combat · sector ${t.id}</span>${helpButton('combat')}</div><button class="btn small" data-cmd="auto-combat">${icon(autoCombat?'pause':'play')} ${autoCombat?'Manual resolution':'Auto-resolve combat'}</button></div><h2>${esc(t.name)} · ${b.stage==='missiles'?'Missile salvo':'Engagement round '+b.round}</h2><div class="battle-sides">${[b.attacker,b.defender].map(id=>`<div class="battle-side"><div class="eyebrow" style="color:${typeof id==='number'?state.players[id].color:'#e6ab7c'}">${id===b.defender?'Defender':'Attacker'}</div><h3>${esc(E.name(state,id))}</h3>${t.ships.filter(u=>u.owner===id).map(u=>unitRow(u,true)).join('')}</div>`).join('')}</div>${die?`<p style="font-size:12px">${esc(E.name(state,die.owner))} rolled. Select a die, then assign its full damage to one eligible target.</p><div class="help-label">Weapon dice${helpButton('hits')}</div><div class="dice">${b.dice.map((d,i)=>`<button class="die ${d.damage===2?'plasma':d.damage===4?'antimatter':''} ${chosenDie===i?'chosen':''}" data-die="${i}" aria-label="Die ${d.roll}, ${d.damage} damage">${d.roll}</button>`).join('')}</div><div class="flex" style="flex-wrap:wrap">${targets.map(u=>`<button class="btn small" data-hit="${u.id}" ${bot&&!paused?'disabled':''}>Hit ${esc(SHIPS[u.type]?.name||u.type)} (${E.stats(state,u.owner,u.type).hull+1-u.damage} HP)</button>`).join('')}${btn('discard-die',targets.length?'Discard die':'No hit — discard',`${bot&&!paused?'disabled':''}`)}</div>`:`<div class="between"><div><p style="font-size:12px">${g?`${esc(E.name(state,g.owner))} · ${esc(SHIPS[g.type]?.name||g.type)} activation`:'Continue to the next engagement round.'}</p><p style="font-size:10px">Defender wins initiative ties. Damage stays until Combat ends.</p></div><div class="flex">${g&&typeof g.owner==='number'&&b.stage==='cannons'&&E.retreatOptions(state,g.owner).length?btn('retreat','Declare retreat',`${bot&&!paused?'disabled':''}`):''}${btn('roll',g?'Roll weapons':'Continue','class="btn primary" '+(bot&&!paused?'disabled':''))}</div></div>`}<div class="battlestatus">${esc(b.log.slice(-2).join(' '))||'Weapons are ready.'}</div></section>`;}
 if(state.phase==='bombardment'){const t=state.sectors[state.bombardSector],human=!state.players[state.bombardOwner].ai;return`<section class="phase-banner"><div class="eyebrow help-label">Population attack${helpButton('bombardment')}</div><h2>${esc(E.name(state,state.bombardOwner))} controls the skies over ${esc(t.name)}</h2><p>Surviving ships fire all cannons once at population. Neutron Bombs and Planta vulnerability are applied automatically. Cubes enter their owner’s graveyard until Cleanup.</p>${btn('bombard','Resolve population attack','class="btn primary" '+(!human&&!paused?'disabled':''))}</section>`;}
 if(state.phase==='conquest'){const t=state.sectors[state.conquestSector],human=!state.players[state.conquestOwner].ai;return`<section class="phase-banner"><div class="eyebrow help-label">Conquest${helpButton('conquest')}</div><h2>${esc(t.name)} is available for control</h2><p>${esc(E.name(state,state.conquestOwner))} may place an influence disc here. Structures remain in place.</p><div class="flex">${btn('conquer','Place influence','class="btn primary" '+(!human&&!paused?'disabled':''))}${btn('skip-conquest','Leave unclaimed',!human&&!paused?'disabled':'')}</div></section>`;}
 if(state.phase==='upkeep'){const p=state.players[state.upkeepIndex],net=p.resources.money+E.income(state,p.id,'money')-E.upkeep(state,p.id),human=!p.ai;return`<section class="phase-banner"><div class="eyebrow help-label">Upkeep · ${esc(p.name)}${helpButton('payUpkeep')}</div><h2>${E.income(state,p.id,'money')} income − ${E.upkeep(state,p.id)} influence cost</h2><p>${net<0?`Bankruptcy: find ${-net} more Money by trading or withdrawing sector influence.`:`Money after upkeep: ${net}. Use remaining colony ships before collecting production.`}</p><div class="flex" style="flex-wrap:wrap">${btn('upkeep','Collect & pay upkeep','class="btn primary" '+(!human&&!paused||net<0?'disabled':''))}${btn('trade','Trade resources',!human&&!paused?'disabled':'')}${btn('colonies','Use colony ships',!human&&!paused||!E.availableColonies(state,p.id).length?'disabled':'')}${net<0&&!E.controlled(state,p.id).length?btn('collapse','Civilization collapse','class="btn danger"'):''}</div></section>`;}
 if(state.phase==='ended'){return`<section class="phase-banner"><div class="eyebrow">The ninth round is complete</div><h2>${esc(E.winner(state)[0].name)} leads the new dawn</h2><p>${state.players.map(p=>`${esc(p.name)}: ${E.totalScore(state,p.id)} VP`).join(' · ')}</p><div class="flex">${btn('new','New game','class="btn primary"')}${btn('export','Export final game')}${btn('score','View scores')}</div></section>`;}return'';}
function exploreDialog(){if(!state.exploration)return;const e=state.exploration;exploreChoice=Math.min(exploreChoice,e.tiles.length-1);const t=e.tiles[exploreChoice];let legal=false;try{E.apply(state,{type:'place',choice:exploreChoice,rotation:exploreRotation,claim:true});legal=true;}catch{}modal('Uncharted space',`<p>Ring ${e.ring} · rotate the sector until at least one wormhole connects to your influence or an unpinned ship. Taking control uses another influence disc.</p>${e.tiles.length>1?`<div class="explore-options">${e.tiles.map((t,i)=>`<button class="choice ${i===exploreChoice?'selected':''}" data-explore-choice="${i}"><b>Sector ${t.id} · ${t.vp} VP</b><span>${t.slots.length} population squares · ${t.ancients} Ancients</span></button>`).join('')}</div>`:''}<div class="explore-preview"><svg viewBox="-88 -80 176 160" style="width:100%;height:100%">${defs()}<g class="sector">${miniSector({...t,owner:null,ships:Array.from({length:t.ancients},()=>({owner:'ancient'})),structures:[]},exploreRotation)}</g></svg></div><div class="between"><span class="tag">${t.ancients} Ancient${t.ancients===1?'':'s'} · ${t.slots.length} squares</span><div class="flex">${btn('rotate-left','↶ Rotate')}${btn('rotate-right','Rotate ↷')}</div></div><div class="species-info">${legal?'Wormhole connection is legal.':`This rotation does not connect. Try another orientation.`} ${t.ancients?'Ancients prevent claiming unless you are the Descendants.':''}</div><label class="flex"><input id="claim-exploration" type="checkbox" checked style="min-height:22px;width:20px;height:20px"> Take control if eligible</label><div class="dialogfooter">${btn('discard-sector','Discard sector')}${btn('place-sector','Place sector','class="btn primary" '+(!legal?'disabled':''))}</div>`);}
function pendingDialog(){const q=state.pending[0];if(!q)return;const p=state.players[q.owner];if(p.ai){schedule();return;}if(q.kind==='discovery'){const r=q.reward,description=RES.includes(r.type)?`Gain ${ {money:8,science:5,materials:6}[r.type]} ${r.type}.`:r.type==='tech'?'Gain the cheapest available technology you do not own.':r.type==='cruiser'?'Place one of your unused Cruisers in this sector.':`Receive the ${PART[r.part].name} Ancient ship part.`;modal('A discovery awaits',`<p>${esc(p.name)} · ${esc(state.sectors[q.sector].name)}</p><div class="explore-preview" style="height:100px;text-align:center;font-size:65px;color:var(--purple)">◈</div><button class="choice" data-discovery="use"><b>Use the discovery</b><span>${esc(description)}</span></button><button class="choice" data-discovery="keep"><b>Keep for 2 victory points</b><span>Save this discovery for final scoring.</span></button>`);}
 if(q.kind==='techDiscovery')modal('Ancient technology',`<p>Choose one of the cheapest available technologies. You pay no Science.</p>${q.choices.map(id=>`<button class="choice" data-free-tech="${id}"><b>${esc(TECH[id].name)}</b><span>${esc(TECH[id].effect)}</span></button>`).join('')}`);
 if(q.kind==='reputation')modal('Combat reputation',`<p>${esc(p.name)} drew ${q.tiles.length} tiles. Keep one and return the others to the bag. ${p.reputation.length>=E.repCapacity(p)?'Your track is full; choose an existing tile to replace, or return this draw.':''}</p><div class="flex" style="justify-content:center;margin:25px 0">${q.tiles.map((v,i)=>`<button class="die ${i===0?'chosen':''}" data-rep-index="${i}">${v}</button>`).join('')}</div><input type="hidden" id="rep-choice" value="0">${p.reputation.length>=E.repCapacity(p)?`<label>Replace existing reputation tile<select id="rep-replace"><option value="">Return the new tile</option>${p.reputation.map((v,i)=>`<option value="${i}">${v} VP tile</option>`).join('')}</select></label>`:''}<div class="dialogfooter">${btn('keep-reputation','Confirm reputation','class="btn primary"')}</div>`);}
function constructionDialog(k){const t=state.sectors[k],p=state.players[me()];selected=k;if(!active('build')){if(!run({type:'begin',action:'build'}))return;}modal('Construct at '+t.name,`<p>${state.active.left} builds remaining · ${p.resources.materials} Materials in storage. Structures are permanent.</p><label>Quantity<input type="number" id="build-count" value="1" min="1" max="${state.active.left}"></label>${Object.entries(SHIPS).map(([id,d])=>{const own=Object.values(state.sectors).flatMap(t=>t.ships).filter(x=>x.owner===p.id&&x.type===id).length;return`<button class="choice" data-build="${id}" data-build-sector="${k}" ${d.tech&&!p.tech.includes(d.tech)||d.parts&&own>=d.limit||!d.parts&&t.structures.includes(id)||p.resources.materials<E.buildCost(p,id)||state.active.left<1?'disabled':''}><b>${esc(d.name)} · ${E.buildCost(p,id)} Materials</b><span>${d.parts?`${own} / ${d.limit} pieces deployed`:d.tech&&!p.tech.includes(d.tech)?'Research '+TECH[d.tech].name+' to unlock':t.structures.includes(id)?'Already present':id==='orbital'?'Adds one Money or Science population square.':'Worth 3 VP when controlled.'}</span></button>`;}).join('')}<div class="dialogfooter">${btn('close','Return to galaxy')}</div>`);}
function tradeDialog(){const id=state.phase==='upkeep'?state.upkeepIndex:me(),p=state.players[id];modal('Bank conversion',`<p>${esc(p.name)} trades at ${SPEC[p.species].trade}:1. Each trade converts ${SPEC[p.species].trade} of the source into one of the destination.</p><div class="setup-grid"><label>Give<select id="trade-from">${RES.map(r=>`<option value="${r}">${r} (${p.resources[r]})</option>`).join('')}</select></label><label>Receive<select id="trade-to">${RES.map(r=>`<option value="${r}" ${r==='science'?'selected':''}>${r}</option>`).join('')}</select></label></div><div class="spacer"></div><label>Number of trades<input id="trade-amount" type="number" value="1" min="1" max="100"></label><div class="dialogfooter">${btn('close','Cancel')}${btn('confirm-trade','Convert resources','class="btn primary" data-player="'+id+'"')}</div>`);}
function colonyDialog(k,i){const id=state.phase==='upkeep'?state.upkeepIndex:me(),choices=E.availableColonies(state,id).filter(x=>x.sector===k&&x.index===i);if(choices.length===1){run({type:'colonize',player:id,...choices[0]});return;}if(!choices.length){toast('This square cannot be colonized right now.');return;}modal('Colonize population square',`<p>Choose which track supplies the population cube.</p>${choices.map(x=>`<button class="choice" data-colonize="${x.res}" data-colonize-sector="${k}" data-colonize-index="${i}" data-player="${id}"><b class="${x.res}">${x.res[0].toUpperCase()+x.res.slice(1)}</b><span>One colony ship is used.</span></button>`).join('')}`);}
function coloniesDialog(){const id=state.phase==='upkeep'?state.upkeepIndex:me(),choices=E.availableColonies(state,id);modal('Deploy colony ships',`<p>${state.players[id].colony} colony ships ready. Choose a world and production type.</p>${choices.map(x=>`<button class="choice" data-colonize="${x.res}" data-colonize-sector="${x.sector}" data-colonize-index="${x.index}" data-player="${id}"><b>${esc(state.sectors[x.sector].name)} · square ${x.index+1}</b><span>${x.res} production</span></button>`).join('')||'<p>No eligible squares.</p>'}`);}
function setupDialog(isNew=true){paused=true;const defaults=['terran','hydran','orion','mechanema','eridani','draco'];modal(loaded||!isNew?'New game':'Welcome to E:NDftG',`<div class="setup-hero"><div class="eyebrow">A new dawn for the galaxy</div><h1>${TITLE}</h1><p>Command a civilization through nine rounds of exploration, technology, diplomacy and war. Play solo against AI or share a device in local hotseat.</p></div><div class="setup-grid"><label>Game mode<select id="setup-mode"><option value="solo" ${setupMode==='solo'?'selected':''}>Solo vs AI</option><option value="hotseat" ${setupMode==='hotseat'?'selected':''}>Local hotseat</option></select></label><label>Players<select id="setup-count">${[2,3,4,5,6].map(n=>`<option value="${n}" ${n===setupCount?'selected':''}>${n} civilizations</option>`).join('')}</select></label></div><div class="spacer"></div><div class="setup-grid"><label>AI difficulty<select id="setup-level">${['easy','normal','hard'].map(l=>`<option value="${l}" ${l===setupLevel?'selected':''}>${l[0].toUpperCase()+l.slice(1)}</option>`).join('')}</select></label><label>Galaxy seed (optional)<input id="setup-seed" type="number" placeholder="Random galaxy"></label></div><div class="section-label">Civilizations</div>${Array.from({length:setupCount},(_,i)=>`<div class="setup-player" style="--player:${COLORS[i]}"><div class="num">${i+1}</div><label>${i===0?'Your civilization':setupMode==='solo'?'AI opponent':'Local commander'}<select data-setup-species="${i}">${SPECIES.map(sp=>`<option value="${sp.id}" ${sp.id===(i===0?setupSpecies:defaults[i])?'selected':''}>${esc(sp.name)}</option>`).join('')}</select></label>${i>0&&setupMode==='solo'?`<label style="flex:.55">Difficulty<select data-setup-difficulty="${i}">${['easy','normal','hard'].map(l=>`<option value="${l}" ${l===setupLevel?'selected':''}>${l}</option>`).join('')}</select></label>`:''}</div>`).join('')}<div class="species-info" id="setup-species-info">${esc(SPEC[setupSpecies].summary)}</div><div class="notice" style="font-size:10px;margin-top:14px;margin-bottom:0">Rules implementation alpha. Some component layouts and faction blueprints are reconstructed. Read Rules & coverage for remaining fidelity gaps.</div><div class="dialogfooter">${loaded?btn('close','Cancel'):''}${btn('start-game','Begin the first dawn '+icon('arrow'),'class="btn primary"')}</div>`);}
function savesDialog(){modal('Save & load',`<p>Autosave and three manual slots are stored in this browser on this device. Export a JSON file to keep a separate backup or transfer your game between a phone and a computer.</p><div class="notice">Browser data can be cleared or evicted. Exported save files preserve your game independently of browser storage.</div><div class="save-slots">${[1,2,3].map(i=>{const info=saveInfo(i);return`<div class="save-slot"><h3>Slot ${i}</h3><p>${info?`${esc(info.label||'Saved game')}<br>Round ${info.round} · ${esc(info.phase)}<br>${date(info.savedAt)}`:'Empty save slot'}</p><div class="save-actions"><button class="btn small" data-save-slot="${i}">Save here</button><button class="btn small" data-load-slot="${i}" ${!info?'disabled':''}>Load</button></div></div>`;}).join('')}</div><div class="spacer"></div><label>Save label<input id="save-label" maxlength="60" placeholder="My galactic campaign"></label><div class="dialogfooter" style="flex-wrap:wrap">${btn('backup','Restore rolling backup')}${btn('import',icon('upload')+' Import file')}${btn('export',icon('download')+' Export file','class="btn primary"')}</div>`);}
function menuDialog(){modal('Command center',`<div class="stack">${btn('saves',icon('save')+' Save & load')}${btn('new',icon('new')+' New game')}${btn('rules',icon('help')+' Rules & coverage')}${btn('show-log',icon('log')+' Galactic chronicle')}${btn('settings',icon('settings')+' AI & display settings')}</div>`);}
function settingsDialog(){modal('AI settings',`<p>Difficulty changes decision policies. Opponents receive no extra resources and use the same legal actions.</p>${state.players.filter(p=>p.ai).map(p=>`<label style="margin:10px 0">${esc(p.name)}<select data-ai-level="${p.id}">${['easy','normal','hard'].map(l=>`<option value="${l}" ${p.difficulty===l?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}<label>AI move pace<select id="ai-speed"><option value="100" ${speed===100?'selected':''}>Fast</option><option value="450" ${speed===450?'selected':''}>Normal</option><option value="1000" ${speed===1000?'selected':''}>Deliberate</option></select></label><div class="spacer"></div>${btn('toggle-pause',paused?'Resume AI':'Pause AI')}`);}
function exportGame(){const blob=new Blob([exportText(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`E-NDftG-round-${state.round}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Save file exported. Use Import file to restore it on any device.');}
function diplomacyDialog(id){const p=state.players[id];modal('Exchange ambassadors',`<p>${esc(p.name)} ${p.ai?'will accept a legal exchange.':'must agree to this exchange on the shared device.'} Each player supplies one population cube from a track of their choice.</p><div class="setup-grid"><label>Your cube<select id="diplomacy-res">${RES.map(r=>`<option value="${r}">${r}</option>`).join('')}</select></label><label>Their cube<select id="diplomacy-other-res">${RES.map(r=>`<option value="${r}">${r}</option>`).join('')}</select></label></div>${!p.ai?'<div class="spacer"></div><label class="flex"><input type="checkbox" id="diplomacy-accepted"> Both players agree</label>':''}<div class="dialogfooter"><button class="btn primary" data-confirm-diplomacy="${id}">Exchange ambassadors</button></div>`);}
function schedule(){clearTimeout(timer);if(paused||helpOpen||document.hidden||$('#dialog').open||state.phase==='ended')return;const a=aiOrder(state,{autoCombat});if(!a)return;timer=setTimeout(()=>{if(!run(a,{silent:true})){paused=true;toast('AI paused after an invalid order. Your game is saved.');render();}},speed);}
document.addEventListener('visibilitychange',()=>schedule());
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-view]');if(!b||b.disabled)return;const d=b.dataset;
 if(d.help){openHelp(d.help,b);return;}
 if(d.helpClose){closeHelp(true);return;}
 if(d.view){view=d.view;draft={};render();return;}
 if(d.action){if(run({type:'begin',action:d.action})){if(d.action==='research')view='research';if(d.action==='upgrade'){view='shipyard';draft={};}render();}return;}
 if(d.ship){moving=d.ship;view='galaxy';render();return;}
 if(d.colony!==undefined){colonyDialog(d.colonySector,Number(d.colony));return;}
 if(d.colonize){closeModal();run({type:'colonize',player:Number(d.player),sector:d.colonizeSector,index:Number(d.colonizeIndex),res:d.colonize});return;}
 if(d.tech){run({type:'research',tech:d.tech,res:'money'});return;}
 if(d.refit){if(run({type:'refit',designs:{[d.refit]:draft[d.refit]}})){delete draft[d.refit];render();}return;}
 if(d.build){const count=Number($('#build-count').value);if(run({type:'build',sector:d.buildSector,ship:d.build,count})){if(state.active.left>0)constructionDialog(d.buildSector);else closeModal();}return;}
 if(d.exploreChoice!==undefined){exploreChoice=Number(d.exploreChoice);exploreDialog();return;}
 if(d.discovery){closeModal();run({type:'discovery',player:state.pending[0].owner,keep:d.discovery==='keep'});return;}
 if(d.freeTech){const id=state.pending[0].owner;closeModal();run({type:'techDiscovery',player:id,tech:d.freeTech,res:'money'});return;}
 if(d.repIndex!==undefined){$('#rep-choice').value=d.repIndex;$('#dialog').querySelectorAll('[data-rep-index]').forEach(x=>x.classList.toggle('chosen',x===b));return;}
 if(d.die!==undefined){chosenDie=Number(d.die);render();return;}
 if(d.hit){run({type:'assign',die:chosenDie,target:d.hit});chosenDie=0;render();return;}
 if(d.saveSlot){try{saveGame(state,d.saveSlot,$('#save-label').value);savesDialog();toast('Game saved in slot '+d.saveSlot+'.');}catch{toast('Device storage is full or unavailable. Export a save file.');}return;}
 if(d.loadSlot){try{state=loadGame(d.loadSlot).game;paused=false;draft={};persist();closeModal();render();schedule();toast('Loaded slot '+d.loadSlot+'.');}catch(err){toast(err.message);}return;}
 if(d.diplomacy){diplomacyDialog(Number(d.diplomacy));return;}
 if(d.confirmDiplomacy){const id=Number(d.confirmDiplomacy);if(run({type:'diplomacy',other:id,res:$('#diplomacy-res').value,otherRes:$('#diplomacy-other-res').value,accepted:state.players[id].ai||$('#diplomacy-accepted').checked}))closeModal();return;}
 const cmd=d.cmd;if(!cmd)return;
 if(cmd==='show-actions'){if(view!=='galaxy'){view='galaxy';render();}$('.actionpanel')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
 if(cmd==='show-phase'){document.querySelector('.combat-banner,.phase-banner')?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 if(['show-map','show-sector','show-research','show-blueprints'].includes(cmd)){const target={'show-map':'.board-panel','show-sector':'.sector-info','show-research':'.tech-grid','show-blueprints':'.design-grid'}[cmd];document.querySelector(target)?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
 if(cmd==='close')closeModal();
 if(cmd==='menu')menuDialog();if(cmd==='new')setupDialog();if(cmd==='saves')savesDialog();if(cmd==='export')exportGame();if(cmd==='import')$('#import-file').click();if(cmd==='settings')settingsDialog();
 if(cmd==='rules'||cmd==='show-log'||cmd==='score'){view=cmd==='rules'?'rules':cmd==='show-log'?'log':'empire';closeModal();render();}
 if(cmd==='toggle-pause'){paused=!paused;closeModal();render();schedule();toast(paused?'AI paused.':'AI resumed.');}
 if(cmd==='auto-combat'){autoCombat=!autoCombat;render();schedule();}
 if(cmd==='zoom-in'||cmd==='zoom-out'||cmd==='fit'){if(cmd==='fit'){zoom=1;pan={x:0,y:0};}else zoom=Math.max(.6,Math.min(4,zoom*(cmd==='zoom-in'?1.25:.8)));render();}
 if(cmd==='start-research'||cmd==='start-upgrade'){const type=cmd==='start-research'?'research':'upgrade';if(run({type:'begin',action:type})){view=type==='research'?'research':'shipyard';draft={};render();}}
 if(cmd==='finish')run({type:'finish'});if(cmd==='pass')run({type:'pass'});if(cmd==='refresh')run({type:'refresh'});if(cmd==='reveal')exploreDialog();if(cmd==='pending')pendingDialog();if(cmd==='trade')tradeDialog();if(cmd==='colonies')coloniesDialog();
 if(cmd==='confirm-trade'){if(run({type:'trade',player:Number(d.player),from:$('#trade-from').value,to:$('#trade-to').value,amount:Number($('#trade-amount').value)}))closeModal();}
 if(cmd==='construction')constructionDialog(d.key);if(cmd==='claim')run({type:'claim',sector:d.key});if(cmd==='withdraw'){if(run({type:'abandon',player:state.phase==='upkeep'?state.upkeepIndex:me(),sector:d.key}))render();}
 if(cmd==='cancel-move'){moving=null;render();}if(cmd==='rotate-left'||cmd==='rotate-right'){exploreRotation=(exploreRotation+(cmd==='rotate-left'?5:1))%6;exploreDialog();}
 if(cmd==='discard-sector'||cmd==='place-sector'){const a={type:'place',discard:cmd==='discard-sector',choice:exploreChoice,rotation:exploreRotation,claim:$('#claim-exploration')?.checked};const target=state.exploration?.key;closeModal();if(run(a)&&target&&!a.discard){selected=target;render();}}
 if(cmd==='keep-reputation'){const q=state.pending[0],idx=Number($('#rep-choice').value),v=$('#rep-replace')?.value;closeModal();run({type:'reputation',player:q.owner,index:idx,replace:v===undefined||v===''?null:Number(v)});}
 if(cmd==='roll')run({type:'combat'});if(cmd==='discard-die'){run({type:'assign',die:chosenDie,discard:true});chosenDie=0;render();}
 if(cmd==='retreat'){const g=E.combatGroup(state);modal('Declare retreat',`<p>All surviving ${esc(SHIPS[g.type].name)} ships will leave on their next activation. They can still be shot before escaping.</p>${E.retreatOptions(state,g.owner).map(k=>`<button class="choice" data-retreat="${k}"><b>${esc(state.sectors[k].name)}</b><span>Controlled sector · no hostile ships</span></button>`).join('')}`);}
 if(cmd==='bombard')run({type:'bombard',player:state.bombardOwner,sector:state.bombardSector});if(cmd==='conquer')run({type:'claim',player:state.conquestOwner,sector:state.conquestSector});if(cmd==='skip-conquest')run({type:'skipConquest'});if(cmd==='upkeep')run({type:'upkeep',player:state.upkeepIndex});if(cmd==='collapse')run({type:'collapse',player:state.upkeepIndex});
 if(cmd==='backup'){try{const v=loadGame('backup');if(!v)throw Error('No rolling backup is available.');state=v.game;paused=true;closeModal();render();toast('Rolling backup restored. AI is paused.');}catch(e){toast(e.message);}}
 if(cmd==='start-game'){try{const players=Array.from({length:setupCount},(_,i)=>({species:$(`[data-setup-species="${i}"]`).value,ai:setupMode==='solo'&&i>0,difficulty:$(`[data-setup-difficulty="${i}"]`)?.value||setupLevel}));const seed=$('#setup-seed').value;state=E.newGame({players,mode:setupMode,difficulty:setupLevel,seed});loaded=true;paused=false;view='galaxy';selected=E.controlled(state,0)[0]?.key;moving=null;zoom=1;pan={x:0,y:0};draft={};autoCombat=false;persist();closeModal();render();schedule();}catch(e){toast(e.message);}}
});
document.addEventListener('click',e=>{const b=e.target.closest('[data-retreat]');if(b){const k=b.dataset.retreat;closeModal();run({type:'combat',retreat:k});}});
document.addEventListener('change',e=>{const el=e.target,d=el.dataset;if(el.id==='setup-count'||el.id==='setup-mode'||el.id==='setup-level'){setupSpecies=$('[data-setup-species="0"]')?.value||setupSpecies;setupCount=Number($('#setup-count').value);setupMode=$('#setup-mode').value;setupLevel=$('#setup-level').value;setupDialog();}
 if(d.setupSpecies==='0'){setupSpecies=el.value;$('#setup-species-info').textContent=SPEC[setupSpecies].summary;}
 if(d.design){const type=d.design;draft[type]??=[...state.players[me()].designs[type].overlay];draft[type][Number(d.slot)]=el.value||null;render();}
 if(d.aiLevel){state.players[Number(d.aiLevel)].difficulty=el.value;persist();render();}
 if(el.id==='ai-speed')speed=Number(el.value);
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Save file exceeds the 5 MB limit.');const imported=parseImport(await file.text());state=imported;paused=true;moving=null;draft={};autoCombat=false;persist();closeModal();render();toast('Game imported. AI is paused; resume when ready.');}catch(e){toast('Could not import: '+e.message);}e.target.value='';});
$('#dialog').addEventListener('close',schedule);
render();if(!loaded)setupDialog();else schedule();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

bindHint(()=>state,modal);
